-- ============================================================================
-- D5: Applied AI and Language Models joins the catalogue, the FIFTH course of
-- the Data & AI module.
--
-- Catalogue row (module 'data_ai'; path_order 70, directly above D4
-- forecastml at 69; prereq_slug NULL, as D1 to D4 carry it: whether D5
-- requires an earlier course is a go-live decision; school left at its
-- default) plus the three capstones and their eighteen graded fields,
-- generated by tools/course-waves/appliedai/gen_course.py from the ENGINE'S
-- OWN RUN (d5_capstone.mjs through the vendored engines/dataai/evaluate.js),
-- which it refuses to write unless fields.json carries exactly that run's
-- values and the tolerance gradedTolerance.js derives. Deep seeds are three
-- separate migrations; the go-live is a fifth and is HELD until a NextGen
-- production upload carries the route /dashboard/apps/appliedai, because the
-- 78 lessons, the teaching lab (evaluateLab.js), its three explorer panels
-- and the capstone case files ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A copilot's retrieval, answers and
-- extractions can be scored deterministically against judged references, so
-- the course teaches retrieving passages and checking cited answers
-- (Associate), scoring retrieval and answers honestly (Professional), and
-- agreement, calibration and the engine's rules (Expert), and grades each
-- tier on its own question with numbers the engine returns. No graded value
-- depends on language-model output; no model runs anywhere in the course.
--
-- THE ENGINE. engines/dataai/evaluate.js, vendored sha-identical with
-- petrolord-engines f50251d, with lib/stats for mulberry32 and the quantile
-- and engines/dataai/ml.js for log loss. Tokens lowercase ASCII split outside
-- [a-z0-9]; TF-IDF as scikit-learn's default; Okapi BM25 with the Lucene idf;
-- ties at 12 significant digits go to the id ascending; recall and AP divide
-- by every relevant judged passage; the ideal DCG uses every judged grade;
-- SQuAD exact match and token F1; groundedness against passages cited AND
-- retrieved; Cohen's kappa; Brier, the reliability table and the Murphy
-- decomposition with the within-bin terms (Stephenson, Coelho and Jolliffe
-- 2008 eq. 7, WBC twice the pooled within-bin covariance); one seeded
-- bootstrap stream.
--
-- WHAT IS GRADED. ORLU (Associate) grades a BM25 idf, a BM25 top score, a
-- TF-IDF top cosine, a mean recall and an MRR at 4, and a pooled supported
-- fraction; NNEWI (Professional) grades a MAP at grade 2, an exponential-gain
-- mean nDCG, a mean token F1, an extraction macro F1, a paired-bootstrap upper
-- bound and a pooled supported fraction; AWKA (Expert) grades unweighted and
-- linear kappa, the Brier score, and REL, RES and WBC at 8 bins. Every value
-- is a return value of the engine, and the data it was run on is in the case
-- file the prompt names.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, a label or
-- a case file, at each field's own shipped tolerance: 0 collisions, and 0
-- pairwise. No prompt states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('appliedai', 'Applied AI and Language Models', 'data_ai', 70, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'appliedai', 'beginner', 'associate',
  'ORLU, 22 passages, 5 queries and their cited answers',
  'Retrieving passages and checking cited answers',
  'ORLU is a synthetic document set of 22 short field passages, ORL-01 to ORL-22, with 5 worded queries, O1 to O5, graded 0 to 3 for relevance, and one cited answer to each query. No language model wrote any of it. One case file comes with this capstone. orlu_case.json carries the passages (id and text), the queries (id and text), the judgments (query id to passage id and grade; a passage not listed for a query is unjudged and counts as grade 0), the answers (query, text and the passages each cites) and, for each answer, the passages its system retrieved, which are that query''s BM25 top 4 at the settings below. The settings: the stop list off; BM25 with k1 1.2 and b 0.75; TF-IDF with raw counts; cutoff k 4; relevant at grade 1 or more; numericRelTol 0. Report six values: the BM25 idf of the term "pressure" over the ORLU passages; the top BM25 score for query O1; the top TF-IDF cosine for query O4; the mean recall at 4 of the BM25 runs over the 5 queries; the MRR at 4 of those runs; and the pooled supported fraction of the 5 answers, each claim checked against the passages the answer cites and retrieved. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','orlu_bm25_idf_pressure', 'label','The BM25 idf of "pressure" over the ORLU passages', 'unit','dimensionless', 'expected',1.120591195386885, 'tol',5e-07),
    jsonb_build_object('key','orlu_o1_bm25_top_score', 'label','The top BM25 score for O1', 'unit','BM25 score', 'expected',7.811644371347484, 'tol',5e-07),
    jsonb_build_object('key','orlu_o4_tfidf_top_cosine', 'label','The top TF-IDF cosine for O4', 'unit','cosine', 'expected',0.4097941058785764, 'tol',5e-07),
    jsonb_build_object('key','orlu_bm25_mean_recall_at4', 'label','The mean recall at 4 of the BM25 runs', 'unit','fraction', 'expected',0.6233333333333333, 'tol',5e-07),
    jsonb_build_object('key','orlu_bm25_mrr_at4', 'label','The MRR at 4 of the BM25 runs', 'unit','dimensionless', 'expected',0.7666666666666666, 'tol',5e-07),
    jsonb_build_object('key','orlu_answers_supported_fraction', 'label','The pooled supported fraction of the ORLU answers', 'unit','fraction', 'expected',0.7619047619047619, 'tol',5e-07)
  )
),
(
  'appliedai', 'intermediate', 'professional',
  'NNEWI, 45 passages, 8 queries and two fixed systems',
  'Scoring retrieval and answers honestly',
  'NNEWI is a synthetic document set of 45 short field passages, NNW-01 to NNW-45, with 8 worded queries, N1 to N8, graded 0 to 3, and the ranked runs of two fixed systems cut at 5: P, BM25 with k1 1.5 and b 0.5, and Q, TF-IDF with sublinear tf on, both with the stop list off. No language model wrote any of it. One case file comes with this capstone. nnewi_case.json carries the passages, the queries, the judgments (a passage not listed for a query is unjudged and counts as grade 0), the runs of P and Q (query id to ranked passage ids, best first), a short answer and its reference to each query, an extraction set (6 fields with their types, the number fields with their absolute tolerances; 14 labelled records, NX-01 to NX-14; 13 predicted records, a record with no prediction being one the system did not extract), and Q''s cited answer to each query, whose retrieved passages are Q''s run for that query. A query with no relevant passage is excluded from every mean; none is. Report six values. First, P''s MAP at 5 with relevant at grade 2 or more. Second, Q''s mean nDCG at 5 with exponential gain (2^grade - 1), the ideal DCG from every judged grade. Third, the mean SQuAD token F1 of the 8 short answers against their references. Fourth, the extraction macro F1 over the 6 fields. Fifth, the upper bound of the paired bootstrap percentile interval of per-query nDCG at 5, linear gain, grade 1, P minus Q, seed 44, 2000 replicates, level 0.95. Sixth, the pooled supported fraction of Q''s answers, numericRelTol 0. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','nnewi_p_map_at5_grade2', 'label','P''s MAP at 5, relevant at grade 2 or more', 'unit','dimensionless', 'expected',0.5791666666666666, 'tol',5e-07),
    jsonb_build_object('key','nnewi_q_ndcg_at5_exponential', 'label','Q''s mean nDCG at 5, exponential gain', 'unit','dimensionless', 'expected',0.6658434450685446, 'tol',5e-07),
    jsonb_build_object('key','nnewi_short_mean_token_f1', 'label','The mean token F1 of the short answers', 'unit','fraction', 'expected',0.7560876623376623, 'tol',5e-07),
    jsonb_build_object('key','nnewi_extraction_macro_f1', 'label','The extraction macro F1', 'unit','fraction', 'expected',0.8148148148148149, 'tol',5e-07),
    jsonb_build_object('key','nnewi_paired_ndcg_upper', 'label','The upper bound of the paired nDCG interval, P minus Q', 'unit','nDCG difference', 'expected',0.08662003730238574, 'tol',5e-07),
    jsonb_build_object('key','nnewi_q_supported_fraction', 'label','The pooled supported fraction of Q''s answers', 'unit','fraction', 'expected',0.5454545454545454, 'tol',5e-07)
  )
),
(
  'appliedai', 'advanced', 'expert',
  'AWKA, 96 rating pairs and 122 calibration rows',
  'Agreement and calibration',
  'AWKA is a synthetic trust set: 96 relevance grades given to the same query and passage pairs by two annotators, rater a and rater b, on the scale 0 to 3, and 122 calibration rows, each an outcome (1 relevant, 0 not) and a stated probability. No language model wrote any of it. One case file comes with this capstone. awka_case.json carries the two raters'' grades, item by item in the same order, and the calibration outcomes and probabilities, row by row in the same order. Report six values. First, Cohen''s kappa of the two raters, unweighted, with the labels 0, 1, 2 and 3. Second, the same kappa with linear weights. Third, the Brier score of the calibration rows. Fourth, fifth and sixth, from the Murphy decomposition at 8 equal-width bins (the edge rule: an interior edge opens the upper bin, and 1 closes the last bin): the reliability REL, the resolution RES, and WBC as Stephenson, Coelho and Jolliffe (2008) label it in their eq. 7 (the fifth term, factor 2 included, so twice the pooled within-bin covariance). All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','awka_kappa_unweighted', 'label','Cohen''s kappa, unweighted', 'unit','dimensionless', 'expected',0.5760869565217391, 'tol',5e-07),
    jsonb_build_object('key','awka_kappa_linear', 'label','Cohen''s kappa, linear weights', 'unit','dimensionless', 'expected',0.7321642088481466, 'tol',5e-07),
    jsonb_build_object('key','awka_brier', 'label','The Brier score', 'unit','dimensionless', 'expected',0.16416885245901644, 'tol',5e-07),
    jsonb_build_object('key','awka_reliability_bins8', 'label','The reliability REL at 8 bins', 'unit','dimensionless', 'expected',0.07224170442589009, 'tol',5e-07),
    jsonb_build_object('key','awka_resolution_bins8', 'label','The resolution RES at 8 bins', 'unit','dimensionless', 'expected',0.0739759723015178, 'tol',5e-07),
    jsonb_build_object('key','awka_wbc_bins8', 'label','The within-bin covariance term WBC at 8 bins (twice the pooled within-bin covariance)', 'unit','dimensionless', 'expected',0.00292706470919057, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
